using System;
using System.Collections.Generic;

enum State { Detached, Added, Unchanged, Modified, Deleted }

class Entry
{
    public string Name; public State S; public int Id;
}

class Program
{
    static void Main()
    {
        // Tracked entries, like the ChangeTracker holds them
        var list = new List<Entry> {
            new Entry { Name = "Ann", S = State.Added },
            new Entry { Name = "Bob", S = State.Unchanged, Id = 2 },
            new Entry { Name = "Cy", S = State.Modified, Id = 3 },
            new Entry { Name = "Di", S = State.Deleted, Id = 4 },
            new Entry { Name = "Ed", S = State.Detached, Id = 5 },
        };
        int nextKey = 100;
        foreach (var e in list) Console.WriteLine("before: " + e.Name + " " + e.S);
        // SaveChanges: one action per state, then move to the end state
        foreach (var e in list)
        {
            switch (e.S)
            {
                case State.Added:
                    e.Id = nextKey++;
                    Console.WriteLine("INSERT " + e.Name + " -> key " + e.Id);
                    e.S = State.Unchanged; break;
                case State.Modified:
                    Console.WriteLine("UPDATE " + e.Name + " WHERE Id=" + e.Id);
                    e.S = State.Unchanged; break;
                case State.Deleted:
                    Console.WriteLine("DELETE " + e.Name + " WHERE Id=" + e.Id);
                    e.S = State.Detached; break;
                default:
                    Console.WriteLine("skip   " + e.Name + " (" + e.S + ")"); break;
            }
        }
        foreach (var e in list) Console.WriteLine("after:  " + e.Name + " " + e.S);
    }
}

using System;
using System.Collections.Generic;

class Customer { public int Id; public string Name; }
class Order { public int Id; public Customer Cust; }

class Program
{
    // Pretend each row of a JOIN materializes a new Customer object
    static List<Order> Query(bool identityResolution)
    {
        var map = new Dictionary<int, Customer>();   // temporary identity map
        var result = new List<Order>();
        int[] custIds = { 1, 1 };                    // two orders, same customer row
        for (int i = 0; i < custIds.Length; i++)
        {
            Customer c;
            if (!identityResolution || !map.TryGetValue(custIds[i], out c))
            {
                c = new Customer { Id = custIds[i], Name = "Acme" };
                map[c.Id] = c;
            }
            result.Add(new Order { Id = i + 1, Cust = c });
        }
        return result;
    }

    static void Main()
    {
        var plain = Query(false);   // AsNoTracking
        var resolved = Query(true); // AsNoTrackingWithIdentityResolution
        Console.WriteLine("AsNoTracking: same Customer object? " +
            ReferenceEquals(plain[0].Cust, plain[1].Cust));
        Console.WriteLine("WithIdentityResolution: same Customer object? " +
            ReferenceEquals(resolved[0].Cust, resolved[1].Cust));
        // Neither version is tracked, so edits would not be saved by SaveChanges.
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static int queries = 0;   // counts round trips to the "database"
    static int[] Parents() { queries++; return new[] { 1, 2, 3, 4, 5 }; }
    static string[] ChildrenOf(int parent) { queries++; return new[] { "c" + parent }; }
    static Dictionary<int, string[]> ChildrenIn(int[] ids)
    {
        queries++;  // WHERE ParentId IN (...)
        return ids.ToDictionary(i => i, i => new[] { "c" + i });
    }

    static void Main()
    {
        var parents = Parents();
        Console.WriteLine("parents: " + string.Join(",", parents));
        // N+1: one query per parent inside the loop
        foreach (var p in parents) ChildrenOf(p);
        Console.WriteLine("N+1 style: " + queries + " queries");

        // Batched: one extra query for all children, then group in memory
        queries = 0;
        parents = Parents();
        var kids = ChildrenIn(parents);
        Console.WriteLine("IN batch:  " + queries + " queries, " + kids.Count + " groups");
        // N parents: N+1 queries versus 2 queries regardless of N
    }
}

using System;
using System.Linq;
using System.Linq.Expressions;

class Program
{
    static int calls = 0;
    static bool Big(int x) { calls++; return x > 3; }

    static void Main()
    {
        // IQueryable operators take Expression<Func<..>>: data, not code
        Expression<Func<int, bool>> expr = x => x > 3 && x % 2 == 0;
        Console.WriteLine("expression tree: " + expr);
        Console.WriteLine("body type: " + expr.Body.NodeType);   // a provider can read this
        var left = ((BinaryExpression)expr.Body).Left;
        Console.WriteLine("left part: " + left);

        // IEnumerable operators take delegates: they just run in memory
        int[] rows = { 1, 2, 3, 4, 5, 6 };
        var q = rows.AsQueryable().Where(x => x > 3);
        Console.WriteLine("queryable expression: " + q.Expression.Type.Name);
        Console.WriteLine("all rows fetched: " + rows.Length);
        var inMemory = rows.AsEnumerable().Where(Big).ToList();
        Console.WriteLine("delegate ran " + calls + " times in C#, kept " + inMemory.Count);
        // With EF the IQueryable version would become: WHERE x > 3 in SQL
    }
}

using System;

class Row { public int Id = 1; public string Name = "Widget"; public int Version = 1; }

class Program
{
    static Row db = new Row();

    // UPDATE ... SET Name=@n, Version=Version+1 WHERE Id=1 AND Version=@orig
    static int Update(string name, int originalVersion)
    {
        if (db.Version != originalVersion) return 0;   // 0 rows affected
        db.Name = name; db.Version++;
        return 1;
    }

    static void Main()
    {
        int aVer = db.Version, bVer = db.Version;      // both users load version 1
        Console.WriteLine("A saves: rows=" + Update("Gadget", aVer));
        int rows = Update("Gizmo", bVer);
        Console.WriteLine("B saves: rows=" + rows);
        if (rows == 0)
        {
            // DbUpdateConcurrencyException: pick a policy
            Console.WriteLine("conflict! db has " + db.Name + " v" + db.Version);
            bVer = db.Version;                          // client wins: take new original
            Console.WriteLine("B retries (client wins): rows=" + Update("Gizmo", bVer));
        }
        Console.WriteLine("final: " + db.Name + " v" + db.Version);
    }
}

using System;

class Program
{
    static void Main()
    {
        int posts = 100, tags = 50;
        // Single query: Blog JOIN Posts JOIN Tags -> every post pairs with every tag
        int single = posts * tags;
        // Split query: 1 row (blog) + posts rows + tags rows, in separate queries
        int split = 1 + posts + tags;
        Console.WriteLine("1 blog, " + posts + " posts, " + tags + " tags");
        Console.WriteLine("single query rows: " + single);
        Console.WriteLine("split queries rows: " + split + " (3 round trips)");
        // Each single-query row also repeats all Blog columns
        Console.WriteLine("blog column copies: single=" + single + " split=1");
        for (int n = 10; n <= 1000; n *= 10)
            Console.WriteLine("n=" + n + " each: single=" + n * n + " split=" + (1 + 2 * n));
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        // New entities and the entities they depend on (foreign keys)
        var dependsOn = new Dictionary<string, string[]> {
            { "OrderLine", new[] { "Order", "Product" } },
            { "Order", new[] { "Customer" } },
            { "Customer", new string[0] },
            { "Product", new string[0] },
        };
        var done = new List<string>();
        var left = new List<string>(dependsOn.Keys);
        // Topological sort: insert an entity only after its principals
        while (left.Count > 0)
        {
            bool progress = false;
            foreach (var e in new List<string>(left))
            {
                bool ready = true;
                foreach (var d in dependsOn[e]) if (!done.Contains(d)) ready = false;
                if (!ready) continue;
                done.Add(e); left.Remove(e); progress = true;
            }
            if (!progress) { Console.WriteLine("cycle: " + string.Join(",", left)); return; }
        }
        Console.WriteLine("INSERT order: " + string.Join(" -> ", done));
        var del = new List<string>(done); del.Reverse();
        Console.WriteLine("DELETE order: " + string.Join(" -> ", del));
    }
}
